/**
 * @name Path Traversal (Non-Vendored)
 * @description Detects path traversal vulnerabilities excluding vendored dependencies.
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-filtered
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fa).getAPathArgument()
  }

  predicate isBarrier(DataFlow::Node node) {
    // Filter out flows that go through vendored code to reduce noise
    node.getLocation().getFile().getAbsolutePath().matches("%/vendored/%")
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
  and not sink.getNode().getLocation().getFile().getAbsolutePath().matches("%/vendored/%")
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name Unsafe Pickle Deserialization
 * @description Deserializing untrusted data with pickle is unsafe.
 * @kind path-problem
 * @problem.severity error
 * @id py/pickle-deserialization
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PickleInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember(["load", "loads"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleInjectionFlow = TaintTracking::Global<PickleInjectionConfig>;
import PickleInjectionFlow::PathGraph

from PickleInjectionFlow::PathNode source, PickleInjectionFlow::PathNode sink
where PickleInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe pickle deserialization from $@.", source.getNode(), "untrusted input"

/**
 * @name SQL Injection via String Concatenation
 * @description Detects SQL injection vulnerabilities where SQL queries are constructed using string concatenation or formatting.
 * @kind path-problem
 * @problem.severity error
 * @id py/snowflake-sql-injection-concat
 * @tags security
 *       external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Sources: Function parameters that are used in SQL construction
    // This assumes that parameters to internal functions might be tainted
    exists(Function f |
        source instanceof DataFlow::ParameterNode and
        source.getScope() = f
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
        // Calls to execute/executemany
        (
            call.getFunction().(DataFlow::AttrRead).getAttributeName() = "execute" or
            call.getFunction().(DataFlow::AttrRead).getAttributeName() = "executemany"
        ) and
        sink = call.getArg(0)
    )
  }

  predicate isBarrier(DataFlow::Node node) {
    // Barrier if the data is parameterized (this is a heuristic)
    // or if it's not a string operation
    none() 
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink, DataFlow::CallCfgNode call
where
    SqlInjectionFlow::flowPath(source, sink) and
    // Ensure the sink is part of a call and that call is actually an SQL execution
    sink.getNode() = call.getArg(0) and
    (
       call.getFunction().(DataFlow::AttrRead).getAttributeName() = "execute" or
       call.getFunction().(DataFlow::AttrRead).getAttributeName() = "executemany"
    ) and
    // We are interested in cases where string formatting/concatenation happens BEFORE the sink
    // The TaintTracking library handles the flow through string operations.
    // We just need to ensure we are catching the right sinks.
    exists( | source.toString() != "" ) // dummy usage

select sink.getNode(), source, sink, "Potential SQL injection from $@ via string manipulation.", source.getNode(), "parameter"
